def transform(grid):
    """Tile the occupied cells with 2x2 squares and oriented L triominoes.

    Squares are color 1. The L triomino's missing corner determines its color:
    upper-left -> 2, lower-left -> 3, lower-right -> 4.
    """
    h, w = len(grid), len(grid[0]) if grid else 0
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    out = [[0] * w for _ in range(h)]
    if not occupied:
        return out

    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= occupied:
                placements.append((box, 1))
            orientations = [
                ((r, c), 2),       # omit upper-left
                ((r + 1, c), 3),   # omit lower-left
                ((r + 1, c + 1), 4),  # omit lower-right
            ]
            for missing, color in orientations:
                piece = box - {missing}
                if piece <= occupied:
                    placements.append((piece, color))

    by_cell = {cell: [] for cell in occupied}
    for piece, color in placements:
        for cell in piece:
            by_cell[cell].append((piece, color))

    # Exact-cover search; choose the most constrained uncovered cell first.
    def search(left):
        if not left:
            return []
        cell = min(left, key=lambda p: sum(piece <= left for piece, _ in by_cell[p]))
        for piece, color in by_cell[cell]:
            if piece <= left:
                rest = search(left - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    solution = search(occupied)
    if solution is None:
        raise ValueError("occupied cells cannot be tiled by the demonstrated pieces")
    for piece, color in solution:
        for r, c in piece:
            out[r][c] = color
    return out
